# Approval policy for an agent's shell commands: deny > allow > ask
ALLOW = {"ls", "cat", "pytest", "git status", "git diff"}
DENY_WORDS = ["rm -rf", "curl", "sudo", "git push"]

def decide(cmd):
    if any(w in cmd for w in DENY_WORDS):
        return "DENY"
    if cmd in ALLOW or cmd.split()[0] in ALLOW:
        return "ALLOW"
    return "ASK"        # default mode: a human must approve

cmds = ["ls", "pytest -q", "git diff", "rm -rf /tmp/x", "curl http://host/x.sh",
        "pip install foo", "git push origin main"]
for c in cmds:
    print(c.ljust(24), decide(c))
# Allowlists are strict by default: anything unknown falls to a human.
